// encoder.mjs — bencode encoder.
//
// Encodes the shared value model into a bencode string:
//   - binary-form strings (latin1: charCode === byte) -> `<length>:<data>`
//   - BigInt / Number integers                        -> `i<decimal>e`
//   - Array (list)                                    -> `l<item>...e`
//   - Map (dict)                                      -> `d<key><value>...e`
//
// Dict keys are sorted ascending by byte value before encoding, matching
// the behavior of Python's `bencoder` package.

// Compare two binary-form strings by byte value (char codes are 0-255,
// so plain relational comparison on chars gives byte order).
function compareKeys(a, b) {
  const len = Math.min(a.length, b.length);
  for (let i = 0; i < len; i++) {
    const ca = a.charCodeAt(i);
    const cb = b.charCodeAt(i);
    if (ca !== cb) return ca - cb;
  }
  return a.length - b.length;
}

// Encode a single value into its bencode representation (a binary-form string).
export function encode(value) {
  // Byte string: the string's length IS the byte count (latin1 form).
  if (typeof value === 'string') {
    return value.length + ':' + value;
  }

  // Integer: BigInt preferred; plain Numbers accepted if they are integers.
  if (typeof value === 'bigint') {
    return 'i' + value.toString() + 'e';
  }
  if (typeof value === 'number') {
    if (!Number.isInteger(value)) {
      throw new TypeError(`Cannot bencode non-integer number: ${value}`);
    }
    return 'i' + value.toString() + 'e';
  }

  // List: concatenated encoded items between `l` and `e`.
  if (Array.isArray(value)) {
    let out = 'l';
    for (const item of value) {
      out += encode(item);
    }
    return out + 'e';
  }

  // Dict: keys sorted ascending by byte order, each key encoded as a
  // string immediately followed by its encoded value.
  if (value instanceof Map) {
    const keys = [...value.keys()];
    for (const key of keys) {
      if (typeof key !== 'string') {
        throw new TypeError(`Bencode dict keys must be strings, got: ${typeof key}`);
      }
    }
    keys.sort(compareKeys);
    let out = 'd';
    for (const key of keys) {
      out += encode(key) + encode(value.get(key));
    }
    return out + 'e';
  }

  throw new TypeError(`Unsupported type for bencode: ${typeof value}`);
}

export default encode;

