/**
 * pyrepr.mjs
 *
 * Mimics Python's repr() for the shared bencode value representation:
 *   - byte strings: JS strings in binary/latin1 form -> Python bytes literals
 *   - integers: BigInt (or Number) -> plain decimal
 *   - lists: plain JS Array -> [item, item]
 *   - dicts: JS Map -> {key: value, ...} in insertion order
 */

/**
 * Render a binary-form string as a Python bytes literal.
 *
 * Quote selection mirrors CPython: prefer single quotes, but switch to
 * double quotes when the data contains `'` and does not contain `"`.
 * Escapes: backslash as `\\`, the active quote char escaped, `\t`, `\n`,
 * `\r`, printable ASCII (0x20-0x7E) literal, everything else `\xHH`
 * (lowercase, two hex digits).
 *
 * @param {string} s binary-form string (each char code 0-255 is one byte)
 * @returns {string} e.g. b'hello' or b"x'y"
 */
function reprBytes(s) {
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";

  let out = 'b' + quote;
  for (let i = 0; i < s.length; i++) {
    const code = s.charCodeAt(i);
    if (code === 0x5c) {          // backslash
      out += '\\\\';
    } else if (s[i] === quote) {  // active quote char
      out += '\\' + quote;
    } else if (code === 0x09) {
      out += '\\t';
    } else if (code === 0x0a) {
      out += '\\n';
    } else if (code === 0x0d) {
      out += '\\r';
    } else if (code >= 0x20 && code <= 0x7e) {
      out += s[i];                // printable ASCII
    } else {
      out += '\\x' + code.toString(16).padStart(2, '0');
    }
  }
  return out + quote;
}

/**
 * Mimic Python's repr() for a value in the shared bencode representation.
 *
 * @param {string|bigint|number|Array|Map} value
 * @returns {string}
 */
export function pyRepr(value) {
  if (typeof value === 'string') {
    return reprBytes(value);
  }
  if (typeof value === 'bigint' || typeof value === 'number') {
    // BigInt#toString and Number#toString both yield plain decimal here.
    return value.toString();
  }
  if (Array.isArray(value)) {
    return '[' + value.map(pyRepr).join(', ') + ']';
  }
  if (value instanceof Map) {
    const entries = [];
    for (const [k, v] of value) {
      entries.push(pyRepr(k) + ': ' + pyRepr(v));
    }
    return '{' + entries.join(', ') + '}';
  }
  throw new TypeError(`pyRepr: unsupported value type: ${typeof value}`);
}

export default pyRepr;

