// Bencode decoder: parses a binary-form string (one char = one byte) into
// the shared value representation:
//   byte strings -> JS string (latin1/binary form, charCodeAt(i) is one byte)
//   integers     -> BigInt (arbitrary precision, like Python ints)
//   lists        -> Array
//   dicts        -> Map (keys are binary-form strings, in the order encountered)

// Decode a complete bencoded value from `data` (a binary-form string).
// Throws an Error on malformed input or trailing garbage.
export function decode(data) {
  if (typeof data !== 'string') {
    throw new Error(`decode: expected a binary-form string, got ${typeof data}`);
  }
  const parser = new Parser(data);
  const value = parser.parseValue();
  if (parser.pos !== data.length) {
    throw new Error(
      `decode: trailing garbage at position ${parser.pos} after complete value`
    );
  }
  return value;
}

export default decode;

// Internal recursive-descent parser with a position cursor.
class Parser {
  constructor(data) {
    this.data = data;
    this.pos = 0;
  }

  // Peek at the current character (or undefined past the end).
  peek() {
    return this.data[this.pos];
  }

  fail(message) {
    throw new Error(`decode: ${message} at position ${this.pos}`);
  }

  // Dispatch on the leading byte: 'i' integer, 'l' list, 'd' dict,
  // digit -> byte string.
  parseValue() {
    const ch = this.peek();
    if (ch === undefined) {
      this.fail('unexpected end of input');
    }
    if (ch === 'i') return this.parseInteger();
    if (ch === 'l') return this.parseList();
    if (ch === 'd') return this.parseDict();
    if (ch >= '0' && ch <= '9') return this.parseString();
    this.fail(`unexpected character ${JSON.stringify(ch)}`);
  }

  // `i<N>e` where N is a decimal integer, optionally negative.
  parseInteger() {
    this.pos++; // consume 'i'
    const start = this.pos;
    if (this.peek() === '-') this.pos++;
    while (this.peek() >= '0' && this.peek() <= '9') this.pos++;
    const digits = this.data.slice(start, this.pos);
    if (this.peek() !== 'e') {
      this.fail('unterminated integer (missing "e")');
    }
    this.pos++; // consume 'e'
    // Validate the digit run before handing it to BigInt so we control
    // the error message. BigInt() itself would also reject junk.
    if (!/^-?\d+$/.test(digits)) {
      throw new Error(
        `decode: invalid integer ${JSON.stringify(digits)} at position ${start}`
      );
    }
    if (digits.length > 1 && digits[0] === '0') {
      throw new Error(
        `decode: integer with leading zero ${JSON.stringify(digits)} at position ${start}`
      );
    }
    if (digits.startsWith('-0')) {
      throw new Error(
        `decode: negative zero / leading zero in integer ${JSON.stringify(digits)} at position ${start}`
      );
    }
    return BigInt(digits);
  }

  // `<len>:<bytes>` — len is a non-negative decimal length in bytes.
  parseString() {
    const start = this.pos;
    while (this.peek() >= '0' && this.peek() <= '9') this.pos++;
    if (this.peek() !== ':') {
      this.fail('missing ":" after string length');
    }
    const lenText = this.data.slice(start, this.pos);
    this.pos++; // consume ':'
    if (lenText.length === 0) {
      throw new Error(`decode: empty string length at position ${start}`);
    }
    if (lenText.length > 1 && lenText[0] === '0') {
      throw new Error(
        `decode: string length with leading zero ${JSON.stringify(lenText)} at position ${start}`
      );
    }
    const len = Number(lenText);
    if (!Number.isSafeInteger(len)) {
      throw new Error(`decode: string length too large at position ${start}`);
    }
    if (this.pos + len > this.data.length) {
      this.fail(
        `string of length ${len} runs past end of input (${this.data.length - this.pos} bytes left)`
      );
    }
    const value = this.data.slice(this.pos, this.pos + len);
    this.pos += len;
    return value;
  }

  // `l<value>...e`
  parseList() {
    this.pos++; // consume 'l'
    const items = [];
    while (this.peek() !== 'e') {
      if (this.peek() === undefined) {
        this.fail('unterminated list (missing "e")');
      }
      items.push(this.parseValue());
    }
    this.pos++; // consume 'e'
    return items;
  }

  // `d<key><value>...e` — keys are byte strings; insertion order is kept.
  parseDict() {
    this.pos++; // consume 'd'
    const map = new Map();
    while (this.peek() !== 'e') {
      const ch = this.peek();
      if (ch === undefined) {
        this.fail('unterminated dict (missing "e")');
      }
      if (!(ch >= '0' && ch <= '9')) {
        this.fail(`dict key must be a byte string, got ${JSON.stringify(ch)}`);
      }
      const key = this.parseString();
      map.set(key, this.parseValue());
    }
    this.pos++; // consume 'e'
    return map;
  }
}

