// Minimal argparse mimic for this script's CLI: three required options
// --a (str), --b (str), --c (int), plus -h/--help.
// Reproduces Python argparse's usage/error format and exit codes.

import process from 'node:process';

// argparse uses basename(sys.argv[0]) as the program name.
function progName() {
  const p = process.argv[1] || '';
  const parts = p.split('/');
  return parts[parts.length - 1] || p;
}

const OPTION_NAMES = ['--a', '--b', '--c']; // definition order

function usageLine() {
  return `usage: ${progName()} [-h] --a A --b B --c C`;
}

// Python repr() of a str: single quotes preferred, double quotes when the
// string contains ' but not "; escapes for backslash, \t, \n, \r and
// non-printable characters as \xHH.
function pyStrRepr(s) {
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    const code = ch.codePointAt(0);
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + quote;
    else if (ch === '\t') out += '\\t';
    else if (ch === '\n') out += '\\n';
