1	// encoder.mjs — bencode encoder.
2	//
3	// Encodes the shared value model into a bencode string:
4	//   - binary-form strings (latin1: charCode === byte) -> `<length>:<data>`
5	//   - BigInt / Number integers                        -> `i<decimal>e`
6	//   - Array (list)                                    -> `l<item>...e`
7	//   - Map (dict)                                      -> `d<key><value>...e`
8	//
9	// Dict keys are sorted ascending by byte value before encoding, matching
10	// the behavior of Python's `bencoder` package.
11	
12	// Compare two binary-form strings by byte value (char codes are 0-255,
13	// so plain relational comparison on chars gives byte order).
14	function compareKeys(a, b) {
15	  const len = Math.min(a.length, b.length);
16	  for (let i = 0; i < len; i++) {
17	    const ca = a.charCodeAt(i);
18	    const cb = b.charCodeAt(i);
19	    if (ca !== cb) return ca - cb;
20	  }
21	  return a.length - b.length;
22	}
23	
24	// Encode a single value into its bencode representation (a binary-form string).
25	export function encode(value) {
26	  // Byte string: the string's length IS the byte count (latin1 form).
27	  if (typeof value === 'string') {
28	    return value.length + ':' + value;
29	  }
30	
31	  // Integer: BigInt preferred; plain Numbers accepted if they are integers.
32	  if (typeof value === 'bigint') {
33	    return 'i' + value.toString() + 'e';
34	  }
35	  if (typeof value === 'number') {
36	    if (!Number.isInteger(value)) {
37	      throw new TypeError(`Cannot bencode non-integer number: ${value}`);
38	    }
39	    return 'i' + value.toString() + 'e';
40	  }
41	
42	  // List: concatenated encoded items between `l` and `e`.
43	  if (Array.isArray(value)) {
44	    let out = 'l';
45	    for (const item of value) {
46	      out += encode(item);
47	    }
48	    return out + 'e';
49	  }
50	
51	  // Dict: keys sorted ascending by byte order, each key encoded as a
52	  // string immediately followed by its encoded value.
53	  if (value instanceof Map) {
54	    const keys = [...value.keys()];
55	    for (const key of keys) {
56	      if (typeof key !== 'string') {
57	        throw new TypeError(`Bencode dict keys must be strings, got: ${typeof key}`);
58	      }
59	    }
60	    keys.sort(compareKeys);
61	    let out = 'd';
62	    for (const key of keys) {
63	      out += encode(key) + encode(value.get(key));
64	    }
65	    return out + 'e';
66	  }
