2	 * pyrepr.mjs
3	 *
4	 * Mimics Python's repr() for the shared bencode value representation:
5	 *   - byte strings: JS strings in binary/latin1 form -> Python bytes literals
6	 *   - integers: BigInt (or Number) -> plain decimal
7	 *   - lists: plain JS Array -> [item, item]
8	 *   - dicts: JS Map -> {key: value, ...} in insertion order
9	 */
10	
11	/**
12	 * Render a binary-form string as a Python bytes literal.
13	 *
14	 * Quote selection mirrors CPython: prefer single quotes, but switch to
15	 * double quotes when the data contains `'` and does not contain `"`.
16	 * Escapes: backslash as `\\`, the active quote char escaped, `\t`, `\n`,
17	 * `\r`, printable ASCII (0x20-0x7E) literal, everything else `\xHH`
18	 * (lowercase, two hex digits).
19	 *
20	 * @param {string} s binary-form string (each char code 0-255 is one byte)
21	 * @returns {string} e.g. b'hello' or b"x'y"
22	 */
23	function reprBytes(s) {
24	  const hasSingle = s.includes("'");
25	  const hasDouble = s.includes('"');
26	  const quote = hasSingle && !hasDouble ? '"' : "'";
27	
28	  let out = 'b' + quote;
29	  for (let i = 0; i < s.length; i++) {
30	    const code = s.charCodeAt(i);
31	    if (code === 0x5c) {          // backslash
32	      out += '\\\\';
33	    } else if (s[i] === quote) {  // active quote char
34	      out += '\\' + quote;
35	    } else if (code === 0x09) {
36	      out += '\\t';
37	    } else if (code === 0x0a) {
38	      out += '\\n';
39	    } else if (code === 0x0d) {
40	      out += '\\r';
41	    } else if (code >= 0x20 && code <= 0x7e) {
42	      out += s[i];                // printable ASCII
43	    } else {
44	      out += '\\x' + code.toString(16).padStart(2, '0');
45	    }
46	  }
47	  return out + quote;
48	}
49	
50	/**
51	 * Mimic Python's repr() for a value in the shared bencode representation.
52	 *
53	 * @param {string|bigint|number|Array|Map} value
54	 * @returns {string}
55	 */
56	export function pyRepr(value) {
57	  if (typeof value === 'string') {
58	    return reprBytes(value);
59	  }
60	  if (typeof value === 'bigint' || typeof value === 'number') {
61	    // BigInt#toString and Number#toString both yield plain decimal here.
62	    return value.toString();
63	  }
64	  if (Array.isArray(value)) {
65	    return '[' + value.map(pyRepr).join(', ') + ']';
66	  }
67	  if (value instanceof Map) {
68	    const entries = [];
69	    for (const [k, v] of value) {
70	      entries.push(pyRepr(k) + ': ' + pyRepr(v));
71	    }
72	    return '{' + entries.join(', ') + '}';
73	  }
74	  throw new TypeError(`pyRepr: unsupported value type: ${typeof value}`);
75	}
