77	export default pyRepr;

1	// Minimal argparse mimic for this script's CLI: three required options
2	// --a (str), --b (str), --c (int), plus -h/--help.
3	// Reproduces Python argparse's usage/error format and exit codes.
4	
5	import process from 'node:process';
6	
7	// argparse uses basename(sys.argv[0]) as the program name.
8	function progName() {
9	  const p = process.argv[1] || '';
10	  const parts = p.split('/');
11	  return parts[parts.length - 1] || p;
12	}
13	
14	const OPTION_NAMES = ['--a', '--b', '--c']; // definition order
15	
16	function usageLine() {
17	  return `usage: ${progName()} [-h] --a A --b B --c C`;
18	}
19	
20	// Python repr() of a str: single quotes preferred, double quotes when the
21	// string contains ' but not "; escapes for backslash, \t, \n, \r and
22	// non-printable characters as \xHH.
23	function pyStrRepr(s) {
24	  const hasSingle = s.includes("'");
25	  const hasDouble = s.includes('"');
26	  const quote = hasSingle && !hasDouble ? '"' : "'";
27	  let out = quote;
28	  for (const ch of s) {
29	    const code = ch.codePointAt(0);
30	    if (ch === '\\') out += '\\\\';
31	    else if (ch === quote) out += '\\' + quote;
32	    else if (ch === '\t') out += '\\t';
33	    else if (ch === '\n') out += '\\n';
34	    else if (ch === '\r') out += '\\r';
35	    else if (code >= 0x20 && code < 0x7f) out += ch;
36	    else out += `\\x${code.toString(16).padStart(2, '0')}`;
37	  }
38	  return out + quote;
39	}
40	
41	// Print argparse's two-line error and exit(2).
42	function errorExit(message) {
43	  process.stderr.write(usageLine() + '\n');
44	  process.stderr.write(`${progName()}: error: ${message}\n`);
45	  process.exit(2);
46	}
47	
48	// Print help to stdout and exit(0), like argparse's -h/--help action.
49	function printHelpAndExit() {
50	  const lines = [
51	    usageLine(),
52	    '',
53	    'options:',
54	    '  -h, --help  show this help message and exit',
55	    '  --a A',
56	    '  --b B',
57	    '  --c C',
58	  ];
59	  process.stdout.write(lines.join('\n') + '\n');
60	  process.exit(0);
61	}
