63	// Mimic Python int(str): strip whitespace, optional sign, digits only.
64	function parseIntValue(raw) {
65	  const trimmed = raw.trim();
66	  if (!/^[+-]?\d+$/.test(trimmed)) {
67	    errorExit(`argument --c: invalid int value: ${pyStrRepr(raw)}`);
68	  }
69	  return BigInt(trimmed);
