72	// Parse argv (already sliced, i.e. process.argv.slice(2)).
73	// Returns { a: string, b: string, c: BigInt } or exits on error/help.
74	export function parseArgs(argv) {
75	  const values = {}; // keyed by option name without dashes
76	  const extras = []; // unrecognized arguments, reported together
77	
78	  let i = 0;
79	  while (i < argv.length) {
80	    const token = argv[i];
81	
82	    if (token === '-h' || token === '--help') {
83	      printHelpAndExit();
84	    }
85	
86	    // Split "--name=value" form; plain "--name" leaves inlineValue undefined.
87	    let name = token;
88	    let inlineValue;
89	    if (token.startsWith('--')) {
90	      const eq = token.indexOf('=');
91	      if (eq !== -1) {
92	        name = token.slice(0, eq);
93	        inlineValue = token.slice(eq + 1);
94	      }
95	    }
96	
97	    if (OPTION_NAMES.includes(name)) {
98	      let value;
99	      if (inlineValue !== undefined) {
100	        value = inlineValue;
101	      } else {
102	        if (i + 1 >= argv.length) {
103	          errorExit(`argument ${name}: expected one argument`);
104	        }
105	        value = argv[i + 1];
106	        i += 1;
107	      }
108	      values[name.slice(2)] = value;
109	    } else {
110	      extras.push(token);
111	    }
112	    i += 1;
113	  }
114	
115	  if (extras.length > 0) {
116	    errorExit(`unrecognized arguments: ${extras.join(' ')}`);
117	  }
118	
119	  // Report all missing required options, in definition order.
120	  const missing = OPTION_NAMES.filter((n) => !(n.slice(2) in values));
121	  if (missing.length > 0) {
122	    errorExit(`the following arguments are required: ${missing.join(', ')}`);
123	  }
124	
125	  return { a: values.a, b: values.b, c: parseIntValue(values.c) };
126	}
