import process from 'node:process';

import { encode } from './lib/bencode/encoder.mjs';
import { decode } from './lib/bencode/decoder.mjs';
import { pyRepr } from './lib/pyrepr.mjs';
import { parseArgs } from './lib/argparse.mjs';

// Mimic str.encode('ascii'): every character must be ASCII (charCode <= 127),
// otherwise Python raises UnicodeEncodeError and the program exits with 1.
function encodeAscii(s) {
  for (let i = 0; i < s.length; i++) {
    if (s.charCodeAt(i) > 127) {
      process.stderr.write(
        `UnicodeEncodeError: 'ascii' codec can't encode character ${JSON.stringify(s[i])} in position ${i}: ordinal not in range(128)\n`
      );
      process.exit(1);
    }
  }
  return s; // pure ASCII: binary-form string identical to the source string
}

const args = parseArgs(process.argv.slice(2));

const dict1 = new Map([['first', encodeAscii(args.a)]]);
const dict2 = new Map([['second', encodeAscii(args.b)], ['number', args.c]]);
const combined = [dict1, dict2];
const encoded = encode(combined);
const decoded = decode(encoded);
const encoded_dict1 = encode(dict1);
const encoded_dict2 = encode(dict2);

console.log(pyRepr(encoded));
console.log(pyRepr(decoded));
console.log(pyRepr(encoded_dict1));
console.log(pyRepr(encoded_dict2));

